'use strict';
const storyShotTypes={wide:'Establishing / wide',medium:'Medium shot',close:'Close-up',two:'Two-person shot',shoulder:'Over the shoulder'};
document.querySelector('.studio-toolbar').insertAdjacentHTML('afterbegin','<button id="openStoryShots">Shot builder</button>');
document.body.insertAdjacentHTML('beforeend',`<dialog id="storyShotsDialog"><div class="tool-heading"><div><div class="eyebrow">TELL THE STORY WITH YOUR CAMERA</div><h2>Shot builder</h2></div><button id="closeStoryShots">Close</button></div><div class="story-shot-workspace"><div><canvas id="storyShotPreview" width="640" height="360" aria-label="Shot framing preview"></canvas><p id="storyShotSummary" class="note"></p><div id="storyShotList"></div></div><div><label>Shot<select id="storyShotType">${Object.entries(storyShotTypes).map(([id,name])=>'<option value="'+id+'">'+name+'</option>').join('')}</select></label><label>Subject<select id="storyShotActor"></select></label><label>Other character<select id="storyShotOther"></select></label><label>Start (s)<input id="storyShotAt" type="number" min="0" max="59.9" step="0.1" value="0"></label><label>Ease into shot (s)<input id="storyShotEase" type="number" min="0" max="2" step="0.1" value="0"></label><label>Follow character<input id="storyShotFollow" type="checkbox" checked></label><button id="previewStoryShot">Preview framing</button><button id="addStoryShot" class="primary">Save shot</button><button id="dialogueShotCoverage">Build coverage from dialogue</button><label>Use story shots<input id="enableStoryShots" type="checkbox" checked></label><button id="clearStoryShots">Remove story shots</button><p class="note">A shot holds until the next shot or scene end. Zero ease makes a cut. Story shots take priority over the scene camera route while enabled. Over-the-shoulder framing uses your existing artwork; supply a back-view character image when needed.</p></div></div></dialog>`);
function storyActorBox(o,t){const v=stateAt(o,t),b=bounds(o,{...v,rotation:0}),points=[{x:b.x,y:b.y},{x:b.x+b.w,y:b.y},{x:b.x,y:b.y+b.h},{x:b.x+b.w,y:b.y+b.h}].map(p=>rotatePoint(p,v,v.rotation)),x=Math.min(...points.map(p=>p.x)),y=Math.min(...points.map(p=>p.y));return{x,y,w:Math.max(...points.map(p=>p.x))-x,h:Math.max(...points.map(p=>p.y))-y}}
function storyHeadBox(o,t){const v=stateAt(o,t);if(o.type==='puppet'){const part=o.parts.find(p=>p.role==='head');if(part){const matrix=puppetMatrices(o,v).matrices.get(part.id),points=[{x:part.x-part.pivotX,y:part.y-part.pivotY},{x:part.x+part.width-part.pivotX,y:part.y-part.pivotY},{x:part.x-part.pivotX,y:part.y+part.height-part.pivotY},{x:part.x+part.width-part.pivotX,y:part.y+part.height-part.pivotY}].map(p=>matrix.transformPoint(p)),x=Math.min(...points.map(p=>p.x)),y=Math.min(...points.map(p=>p.y));return{x,y,w:Math.max(...points.map(p=>p.x))-x,h:Math.max(...points.map(p=>p.y))-y}}}if(o.type==='character'){const center=characterLocalToWorld({x:(v.headTurn||0)*12,y:-253},v,o.character),w=108*v.scale*Number(o.character.bodyWidth||1),h=126*v.scale*Number(o.character.height||1);return{x:center.x-w/2,y:center.y-h/2,w,h}}const b=storyActorBox(o,t);return{x:b.x,y:b.y,w:b.w,h:Math.max(20,b.h*.4)}}
function unionStoryBoxes(boxes){if(!boxes.length)return{x:0,y:0,w:960,h:540};const x=Math.min(...boxes.map(b=>b.x)),y=Math.min(...boxes.map(b=>b.y));return{x,y,w:Math.max(...boxes.map(b=>b.x+b.w))-x,h:Math.max(...boxes.map(b=>b.y+b.h))-y}}
function computeStoryCamera(s,shot,t){const subject=s.objects.find(o=>o.id===shot.actorId),other=s.objects.find(o=>o.id===shot.otherId),actors=storyActors(s).filter(o=>visibleAt(o,t,s));let box;if(shot.type==='wide')box=unionStoryBoxes((actors.length?actors:s.objects.filter(o=>visibleAt(o,t,s))).map(o=>storyActorBox(o,t)));else if(!subject)box={x:0,y:0,w:960,h:540};else if(shot.type==='two'){box=unionStoryBoxes([subject,other].filter(Boolean).map(o=>storyActorBox(o,t)))}else{const head=storyHeadBox(subject,t),body=storyActorBox(subject,t);if(shot.type==='close')box={x:head.x-head.w*.3,y:head.y-head.h*.2,w:head.w*1.6,h:head.h*1.8};else if(shot.type==='medium')box={x:body.x-body.w*.1,y:Math.min(body.y,head.y),w:body.w*1.2,h:Math.max(head.h*2,body.h*.68)};else{const listener=other?storyHeadBox(other,t):head,cx=(head.x+head.w/2)*.75+(listener.x+listener.w/2)*.25;box={x:cx-head.w*1.2,y:head.y-head.h*.2,w:head.w*2.4,h:head.h*2.1}}}const view=projectView(),padding=shot.type==='wide'?1.18:1.08,zoom=clamp(Math.min(view.width/(Math.max(20,box.w)*padding),view.height/(Math.max(20,box.h)*padding)),.25,6);return{x:box.x+box.w/2,y:box.y+box.h/2,zoom}}
function storyShotCamera(s,shot,t){return shot.follow?computeStoryCamera(s,shot,t):{...shot.camera}}
function retimeStoryShots(s){for(const shot of s.storyShots||[]){const line=storyLines(s).find(l=>l.id===shot.lineId);if(line){shot.at=clamp(line.start+(shot.lineOffset||0),0,s.duration-.01);shot.camera=computeStoryCamera(s,shot,shot.at)}}s.storyShots=(s.storyShots||[]).sort((a,b)=>a.at-b.at).filter((shot,i,list)=>!list[i+1]||Math.abs(list[i+1].at-shot.at)>.015)}
const cameraBeforeStoryShots=cameraAt;cameraAt=function(s,t){const shots=(s.storyShots||[]).slice().sort((a,b)=>a.at-b.at);if(s.storyShotsEnabled===false||!shots.length||t<shots[0].at)return cameraBeforeStoryShots(s,t);const index=shots.findLastIndex(shot=>shot.at<=t),shot=shots[index],to=storyShotCamera(s,shot,t);if(!shot.ease||t>=shot.at+shot.ease)return to;const from=index>0?storyShotCamera(s,shots[index-1],shot.at):cameraBeforeStoryShots(s,shot.at),f=clamp((t-shot.at)/shot.ease,0,1),ease=f*f*(3-2*f);return{x:from.x+(to.x-from.x)*ease,y:from.y+(to.y-from.y)*ease,zoom:from.zoom+(to.zoom-from.zoom)*ease}};
function shotForm(){return{type:$('storyShotType').value,actorId:$('storyShotActor').value||null,otherId:$('storyShotOther').value||null,at:clamp(+$('storyShotAt').value||0,0,current().duration-.01),ease:clamp(+$('storyShotEase').value||0,0,2),follow:$('storyShotFollow').checked}}
function storeStoryShot(data,s=current()){if((s.storyShots||[]).length>=200)return toast('Keep up to 200 shots per scene.');if(data.type!=='wide'&&!s.objects.some(o=>o.id===data.actorId))return toast('Choose a subject for this shot.');if(['two','shoulder'].includes(data.type)&&(!data.otherId||data.otherId===data.actorId))return toast('Choose two different characters for this shot.');const existing=(s.storyShots||[]).find(shot=>Math.abs(shot.at-data.at)<.015),shot={id:existing?.id||uid(),...data,camera:computeStoryCamera(s,data,data.at)};s.storyShots=(s.storyShots||[]).filter(a=>a!==existing);s.storyShots.push(shot);s.storyShots.sort((a,b)=>a.at-b.at);s.storyShotsEnabled=true;return shot}
async function paintStoryShotPreview(candidate=null){const canvas=$("storyShotPreview"),s=current(),at=candidate?.at??clamp(+$("storyShotAt").value||0,0,s.duration);try{const assets=[s.backgroundImage,...s.objects.flatMap(o=>o.type==='image'?[o.src]:o.type==='puppet'?[...o.parts.map(p=>p.src),...puppetFaceSources(o),...Object.values(o.mouth?.sprites||{})]:o.type==='flipbook'?o.frames.map(f=>f.src):[])].filter(Boolean);await Promise.all(assets.map(src=>imageReady(src).catch(()=>{})));for(const o of s.objects.filter(o=>o.type==='video'&&visibleAt(o,at,s)))await seekVideo(videoFor(o),clamp(o.sourceOffset+(at-clipStart(o))*videoSpeed(o),0,Math.max(0,o.sourceDuration-.01)));if(current()!==s||!$("storyShotsDialog").open)return;const previous=s.storyShots,enabled=s.storyShotsEnabled;try{if(candidate){s.storyShots=[{...candidate,id:'preview',ease:0,camera:computeStoryCamera(s,candidate,at)}];s.storyShotsEnabled=true}renderSceneFrame(canvas.getContext('2d'),s,at);if((project.canvasFormat||'landscape')!=='landscape'){const view=projectView(),c=canvas.getContext('2d');c.fillStyle='#090b11d9';c.fillRect(0,0,view.left/960*640,360);c.fillRect((view.left+view.width)/960*640,0,view.left/960*640,360)}const cam=cameraAt(s,at);$("storyShotSummary").textContent='At '+at.toFixed(2)+'s · '+cam.zoom.toFixed(2)+'× · '+projectView().name}finally{s.storyShots=previous;s.storyShotsEnabled=enabled}}catch(e){toast('Shot preview could not load: '+e.message)}}

function renderStoryShotList(){const list=$('storyShotList'),s=current();list.replaceChildren();for(const shot of s.storyShots||[]){const row=document.createElement('div');row.className='story-shot-row';const name=document.createElement('span');name.textContent=shot.at.toFixed(2)+'s · '+storyShotTypes[shot.type]+' · '+(shot.type==='wide'?'Whole scene':actorName(s,shot.actorId));row.append(name,storyButton('Edit',()=>{for(const[id,key]of[['storyShotType','type'],['storyShotActor','actorId'],['storyShotOther','otherId'],['storyShotAt','at'],['storyShotEase','ease']])$(id).value=shot[key]??'';$('storyShotFollow').checked=shot.follow;paintStoryShotPreview()}),storyButton('See on stage',()=>{$('storyShotsDialog').close();time=shot.at;selectLayers(shot.actorId?[shot.actorId]:[]);render()}),storyButton('Delete',()=>{s.storyShots=s.storyShots.filter(a=>a!==shot);save();render();renderStoryShotList();paintStoryShotPreview()}));list.append(row)}$('enableStoryShots').checked=s.storyShotsEnabled!==false}
function openStoryShots(line=null){stop();if(pathEditor)finishPathEditing();for(const id of ['storyShotActor','storyShotOther']){const e=$(id);e.replaceChildren();const none=document.createElement('option');none.value='';none.textContent='Choose character';e.append(none);for(const o of storyActors(current())){const opt=document.createElement('option');opt.value=o.id;opt.textContent=o.name;e.append(opt)}}const actors=storyActors(current());$('storyShotActor').value=line?.speakerId||object()?.id||actors[0]?.id||'';$('storyShotOther').value=actors.find(o=>o.id!==$('storyShotActor').value)?.id||'';$('storyShotAt').value=+(line?.start??time).toFixed(2);if(line)$('storyShotType').value='close';renderStoryShotList();$('storyShotsDialog').showModal();paintStoryShotPreview()}
$('openStoryShots').onclick=()=>openStoryShots();$('closeStoryShots').onclick=()=>$('storyShotsDialog').close();$('previewStoryShot').onclick=()=>paintStoryShotPreview(shotForm());$('addStoryShot').onclick=()=>{if(!storeStoryShot(shotForm()))return;save();render();renderStoryShotList();paintStoryShotPreview(shotForm());toast('Shot saved on the camera track.')};$('enableStoryShots').onchange=e=>{current().storyShotsEnabled=e.target.checked;save();draw();paintStoryShotPreview()};$('clearStoryShots').onclick=()=>{current().storyShots=[];save();render();renderStoryShotList();paintStoryShotPreview()};
$('dialogueShotCoverage').onclick=()=>{const s=current(),lines=storyLines(s).filter(l=>l.speakerId&&s.objects.some(o=>o.id===l.speakerId));if(!s.dialogueArranged)return toast('Arrange this scene’s conversation first.');if(!lines.length)return toast('Assign dialogue to characters first.');s.storyShots=[];storeStoryShot({type:'wide',actorId:null,otherId:null,at:0,ease:0,follow:false});for(let i=0;i<lines.length;i++){const l=lines[i],at=Math.max(l.start,i===0?.45:0);if(at>=l.start+l.duration||at>=s.duration)continue;const other=lines.slice(0,i).reverse().find(p=>p.speakerId!==l.speakerId)?.speakerId||storyActors(s).find(o=>o.id!==l.speakerId)?.id||null;storeStoryShot({type:'close',actorId:l.speakerId,otherId:other,at,ease:0,follow:true,lineId:l.id,lineOffset:at-l.start})}save();render();renderStoryShotList();paintStoryShotPreview();toast('Establishing shot and speaker close-ups added. Adjust each shot to shape the conversation.')};
const timelineBeforeShots=renderTimeline;renderTimeline=function(){timelineBeforeShots();if(timelineDrag||!current().storyShots?.length)return;const s=current(),offset=sceneOffset(),shots=[...s.storyShots].sort((a,b)=>a.at-b.at),row=lane('Story camera shots','story-camera-track');shots.forEach((shot,i)=>makeClip(row.area,{start:offset+shot.at,end:offset+(shots[i+1]?.at??s.duration),label:storyShotTypes[shot.type]+' · '+actorName(s,shot.actorId),kind:'story-shot',onselect:()=>{time=shot.at},onmove:change=>{if(change.mode!=='move')return;const min=i?shots[i-1].at+.05:0,max=(shots[i+1]?.at??s.duration)-.05;shot.at=clamp(shot.at+change.delta,min,max);delete shot.lineId;shot.camera=computeStoryCamera(s,shot,shot.at);s.storyShots.sort((a,b)=>a.at-b.at);save()}}))};
const shotsValidator=valid;valid=function(p){try{return shotsValidator(p)&&p.scenes.every(s=>(s.storyShotsEnabled===undefined||typeof s.storyShotsEnabled==='boolean')&&(!s.storyShots||Array.isArray(s.storyShots)&&s.storyShots.length<=200&&s.storyShots.every(a=>a&&typeof a.id==='string'&&Object.hasOwn(storyShotTypes,a.type)&&Number.isFinite(a.at)&&a.at>=0&&a.at<s.duration&&Number.isFinite(a.ease)&&a.ease>=0&&a.ease<=2&&typeof a.follow==='boolean'&&['actorId','otherId'].every(k=>a[k]===null||typeof a[k]==='string')&&a.camera&&['x','y','zoom'].every(k=>Number.isFinite(a.camera[k]))&&Math.abs(a.camera.x)<=10000&&Math.abs(a.camera.y)<=10000&&a.camera.zoom>=.25&&a.camera.zoom<=6&&(!a.lineId||typeof a.lineId==='string'&&Number.isFinite(a.lineOffset)))))}catch{return false}};
render();
